// The shape of the data in src/data/ingredients.json.
// That file is generated by scripts/import.mjs from data/ingredients.xlsx.

/** A value Claude filled in because the spreadsheet cell was empty. */
export interface FilledValue {
  source: string | null; // link or name of the reference, if there is one
  check: string | null; // what the reference says, e.g. "PubChem lists 91-64-5 as coumarin."
}

export type FillableField = "cas" | "category" | "odorFamily" | "synonyms" | "ifraRestriction";

export interface Ingredient {
  // --- From your spreadsheet (null / empty when the cell is empty) ---
  id: string; // URL slug made from the name, e.g. "hedione"
  rowNumber: number; // the row in the spreadsheet, so you can find it
  name: string;
  synonyms: string[];
  cas: string[]; // usually one; natural materials can have several; empty if none
  casValid: boolean | null; // passes the CAS check digit? null = no CAS to check
  casNotes: string[]; // e.g. "Excel stored this CAS number as a date..."
  category: string | null;
  odorFamily: string | null;
  odorDescription: string | null;
  supplier: string | null;
  pricePerGram: number | null;
  currency: string | null; // e.g. "USD", taken from the column header
  priceIsCalculated: boolean; // true = worked out as bottle price ÷ size
  calculatedPricePerGram: number | null; // bottle price ÷ size, for comparison
  priceMismatch: boolean; // typed cost/gram differs from cost ÷ size by more than 5%
  priceNote: string | null; // e.g. "Leaves out the $0.90 packaging fee: ..."
  bottlePrice: number | null;
  bottleSizeGrams: number | null;
  ifraRestriction: string | null; // Category 4 limit, from your sheet or filled in (see `filled`)
  averageUse: string | null; // exactly as written in the spreadsheet
  extra: Record<string, string | number>; // columns the import didn't recognise

  // --- Worked out by the import script ---
  wishlist: boolean; // no price, cost or size yet (not bought yet)
  duplicates: string[]; // ids of other rows with the same name
  sameCasAs: string[]; // ids of other ingredients with the same CAS number
  warnings: string[]; // problems worth fixing in the spreadsheet

  // --- Filled in by Claude (from data/filled-in.json), only where your sheet is empty ---
  filled: Partial<Record<FillableField, FilledValue>>;
  filledNote: string | null;
  ifraCheck: FilledValue | null; // what your own IFRA value was checked against
  casCheck: FilledValue | null; // what your own CAS number was checked against

  // --- Reserved for later phases. Not filled in yet. ---
  background?: {
    history?: string;
    discovery?: string;
    naturalOccurrence?: string;
    odorProfile?: string;
  };
  usage?: {
    typicalRangePercent?: { min: number; max: number };
    ifraLimits?: string;
    notes?: string;
  };
  demoFormulas?: DemoFormula[];
  sources?: string[]; // citation URLs or references
}

export interface DemoFormula {
  name: string;
  description?: string;
  ingredients: { ingredientId: string; parts: number }[];
}

export interface IngredientData {
  importedAt: string;
  sourceSheet: string;
  labels: Partial<Record<string, string>>; // field name -> your column header
  ingredients: Ingredient[];
}

// ---------------------------------------------------------------------------
// Formulas (saved in data/formulas.json by the dev server; see formulas-api.ts)
// ---------------------------------------------------------------------------

export interface FormulaLine {
  ingredientId: string; // id from ingredients.json, e.g. "hedione"
  ingredientName: string; // copy of the name, so a renamed ingredient can still be recognised
  grams: number; // weight added to the formula
}

export interface Formula {
  id: string;
  name: string;
  notes: string;
  // How much of this formula goes into the finished product, e.g. 20 for an EdP at 20%.
  // Used for the IFRA check. Null = not set yet.
  concentrationPercent: number | null;
  lines: FormulaLine[];
  createdAt: string; // ISO date
  updatedAt: string; // ISO date
}

// ---------------------------------------------------------------------------
// Published formulas (the formulary) and what the site learned from them.
// Made by scripts/learn-formulas.mjs from data/reference-formulas/*.json.
// ---------------------------------------------------------------------------

export interface PublishedLine {
  name: string; // exactly as published
  amount: number; // as published, in the formula's unit
  dilution?: string; // dilution column, if the source has one ("10%")
  cas?: string;
  dilutionPercent: number | null; // parsed from the name or dilution column; null = neat / not stated
  percent: number; // share of the whole formula
  neatPercent: number; // share as pure material (percent × dilution)
  ingredientIds: string[]; // matching library ingredients (empty = not in Jin's library)
  match: "exact" | "variant" | null; // variant = same material, other grade/dilution/trade name
  solvent?: boolean; // solvent or additive (DPG, alcohol, antioxidant)
}

export interface PublishedFormula {
  id: string;
  title: string;
  kind: "perfume" | "accord" | "home";
  style: string | null; // e.g. "a fruity chypre"
  smellsLike: string | null;
  year: string | null;
  url: string; // the formula itself (PDF or post)
  article: string | null; // blog post about it, if any
  thread?: string | null; // Basenotes discussion thread, if any
  source: string; // "Fraterworks", "Basenotes", ...
  sourceUrl: string;
  unit: string; // "g", "parts", ...
  printedTotal: number | null;
  total: number;
  totalNote: string | null; // when the lines don't add up to the printed total
  note?: string | null; // e.g. other versions printed beside it in the source
  lines: PublishedLine[];
}

export interface FormularyData {
  learnedAt: string;
  sources: { source: string; url: string; about: string[] }[];
  formulas: PublishedFormula[];
}

export interface Partner {
  material: string;
  ingredientIds: string[];
  shared: number; // formulas that use both
  score: number; // 0–1, shared formulas scaled by how common each material is
  examples: string[]; // a few of those formula ids
}

export interface MaterialInsight {
  ingredientIds: string[]; // library rows that are this material
  formulaCount: number;
  formulaIds: string[];
  perfumeCount: number;
  neatPercent: { min: number; p25: number; median: number; p75: number; max: number } | null;
  role: string | null;
  roleMeaning: string | null;
  partners: Partner[];
}

/** What the supplier's product page says about a material (data/supplier-profiles.json). */
export interface SupplierProfile {
  source: "Fraterworks" | "PerfumersWorld";
  url: string;
  classification?: string | null; // "Base Note" (Fraterworks)
  averageUsePercent: number | null; // typical % in a perfume compound
  usage?: { from: number; average: number; max: number } | null; // PerfumersWorld
  odourFamily?: string | null; // Fraterworks
  impression?: { label: string; percent: number }[]; // PerfumersWorld odour profile
  longevityHours: number | null;
  longevity: string | null; // as the supplier words it
  relativeImpact?: number | null; // PerfumersWorld strength scale
  uses?: string[]; // PerfumersWorld usage keywords
  blendsWith: { name: string; ingredientIds: string[] }[];
}

export interface InsightData {
  learnedFrom: number;
  minSharedFormulas: number;
  roles: { min: number; role: string; meaning: string }[];
  materialOf: Record<string, string>; // ingredient id -> material id
  insights: Record<string, MaterialInsight>;
  profiles: Record<string, SupplierProfile>; // ingredient id -> supplier notes
}
